#nullable enable // autogenerated

using MVZ2Logic.Models;
using MVZ2Logic.UI;
using PVZEngine.Tools.Unity;
using TMPro;
using UnityEngine;

namespace MVZ2.GameContent.Models
{
    public class BlueprintSprite : MonoBehaviour
    {
        public void UpdateView(BlueprintViewData viewData)
        {
            costText.text = viewData.cost;
            triggerCostRoot.SetActive(viewData.triggerActive);

            // Styles
            if (standaloneBackground) standaloneBackground.SetSprite(viewData.standaloneBackground);
            if (mobileBackground) mobileBackground.SetSprite(viewData.mobileBackground);
            if (mobileFrameTop) mobileFrameTop.SetSprite(viewData.mobileFrameTop);
            if (mobileFrameBottom) mobileFrameBottom.SetSprite(viewData.mobileFrameBottom);

            var icon = viewData.icon;
            iconRenderer.enabled = icon && !viewData.iconGrayscale;
            iconRenderer.SetSprite(icon);
            iconCommandBlockRenderer.enabled = icon && viewData.iconGrayscale;
            iconCommandBlockRenderer.SetSprite(icon);
            UpdateIcon();
        }
        protected void UpdateIcon()
        {
            var iconSprite = iconRenderer.GetSprite();
            if (!iconSprite.Exists())
                return;
            var spriteScale = new Vector2(iconSprite.rect.width / iconSpriteSize.x, iconSprite.rect.height / iconSpriteSize.y);
            Vector3 iconScale;
            if (lockAspect)
            {
                var maxScale = Mathf.Max(spriteScale.x, spriteScale.y);
                iconScale = Vector3.one * (1 / maxScale);
            }
            else
            {
                iconScale = new Vector3(1 / spriteScale.x, 1 / spriteScale.y);
            }
            iconRoot.localScale = iconScale;
        }
        [SerializeField]
        protected Transform iconRoot = null!;
        [SerializeField]
        protected SpriteRendererResolver iconRenderer = null!;
        [SerializeField]
        protected SpriteRendererResolver iconCommandBlockRenderer = null!;
        [SerializeField]
        protected GameObject triggerCostRoot = null!;
        [SerializeField]
        protected TextMeshPro costText = null!;

        [SerializeField]
        protected Vector2 iconSpriteSize;

        [Header("Styles (Standalone)")]
        [SerializeField]
        private SpriteRendererResolver standaloneBackground = null!;

        [Header("Styles (Mobile)")]
        [SerializeField]
        private SpriteRendererResolver mobileBackground = null!;
        [SerializeField]
        private SpriteRendererResolver mobileFrameTop = null!;
        [SerializeField]
        private SpriteRendererResolver mobileFrameBottom = null!;

        [SerializeField]
        protected bool lockAspect;
    }
}
